    local DiscordBtn = Instance.new("TextButton")
    DiscordBtn.Size = UDim2.new(0.5, -20, 0, 38)
    DiscordBtn.Position = UDim2.new(0.5, 5, 0, 155)
    DiscordBtn.BackgroundColor3 = Color3.fromRGB(25, 35, 48)
    DiscordBtn.BorderSizePixel = 0
